    "#Data\n",
    "df = pd.read_csv(\"/kaggle/input/notebooks/smessenger/notebook957b6bbc9e/strategy1/master_labels_s1.csv\")\n",
    "\n",
    "train_df = df[df[\"split\"] == \"train\"].reset_index(drop=True)\n",
    "val_df   = df[df[\"split\"] == \"val\"].reset_index(drop=True)\n",
    "test_df  = df[df[\"split\"] == \"test\"].reset_index(drop=True)\n",
    "\n",
    "transform = transforms.Compose([\n",
    "    transforms.Resize((224,224)),\n",
    "    transforms.ToTensor(),\n",
    "    transforms.Normalize(\n",
    "        mean=[0.7236, 0.6037, 0.8287],\n",
    "        std=[0.1449, 0.1477, 0.0756]\n",
    "    )\n",
    "])\n",
    "\n",
    "train_ds_100_1 = CSVDataset(train_df, img_col=\"path_100\", transform=transform)\n",
    "val_ds_100_1   = CSVDataset(val_df, img_col=\"path_100\", transform=transform)\n",
    "test_ds_100_1  = CSVDataset(test_df,img_col=\"path_100\", transform=transform)\n",
    "\n",
    "id2label = {0: \"Tumor\", 1: \"DCIS_1\", 2: \"DCIS_2\"}\n",
    "label2id = {v: k for k, v in id2label.items()}\n",
    "\n",
    "\n",
    "# for param in model_100_1.vit.parameters():\n",
    "#     param.requires_grad = False\n",
    "\n",
    "def freeze_vit_except_last_blocks(model, num_trainable_blocks):\n",
    "\n",
    "    for param in model.vit.parameters():\n",
    "        param.requires_grad = False\n",
    "\n",
    "    # Unfreeze final encoder blocks\n",
    "    if num_trainable_blocks > 0:\n",
    "        for block in model.vit.encoder.layer[-num_trainable_blocks:]:\n",
    "            for param in block.parameters():\n",
    "                param.requires_grad = True\n",
    "\n",
    "    # train classifier\n",
    "    for param in model.classifier.parameters():\n",
    "        param.requires_grad = True\n",
    "\n",
    "def compute_metrics(eval_pred):\n",
    "    logits, labels = eval_pred\n",
    "    preds = np.argmax(logits, axis=1)\n",
    "\n",
    "    return {\n",
    "        \"accuracy\": accuracy_score(labels, preds),\n",
    "        \"f1_macro\": f1_score(labels, preds, average=\"macro\"),\n",
    "        \"f1_per_class\": f1_score(labels, preds, average=None).tolist(),\n",
    "        \"kappa\": cohen_kappa_score(labels, preds)\n",
    "    }\n",
    "\n",
    "\n",
    "blocks = 2 \n",
    "\n",
    "train_args = TrainingArguments(\n",
    "    output_dir = \"output-models\",\n",
    "    save_total_limit=2,\n",
    "    save_strategy=\"epoch\",\n",
    "    eval_strategy=\"epoch\",\n",
    "    learning_rate=1e-5,\n",
